<?php
if(!function_exists('ml_guard_deny')){function ml_guard_deny(){if(!headers_sent()){header('HTTP/1.1 404 Not Found');header('Status: 404 Not Found');$a=isset($_SERVER['HTTP_ACCEPT'])?(string)$_SERVER['HTTP_ACCEPT']:'';$b=(strpos($a,'application/json')!==false);if($b){header('Content-Type: application/json; charset=utf-8');echo'{"success":false,"error":"Not Found"}';}else{header('Content-Type: text/html; charset=utf-8');echo'<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8">'.'<meta name="viewport" content="width=device-width,initial-scale=1">'.'<title>404 Not Found</title></head>'.'<body style="margin:0;min-height:100vh;display:flex;align-items:center;'.'justify-content:center;font-family:-apple-system,\'Segoe UI\',\'Microsoft YaHei\',sans-serif;'.'background:#f8fafc;color:#64748b">'.'<div style="text-align:center"><div style="font-size:58px;font-weight:700;color:#cbd5e1">404</div>'.'<div style="margin-top:6px;font-size:14px">Not Found</div></div>'.'</body></html>';}}exit;}}if(!function_exists('ml_guard_boot')){function ml_guard_boot($a){$a=(string)$a;if($a===''){return;}$b=($a==='/install.php'||$a==='/install'||$a==='/install/');if(!$b&&preg_match('#^/(install|setup|upgrade|update)([-_.][a-z0-9]+)?(\.[a-z0-9]+)?(/|$)#i',$a)){ml_guard_deny();}if(preg_match('#^/(config|sql|core|adapters|cron|tools|data|logs|backup|bak)(/|$)#i',$a)){ml_guard_deny();}if(preg_match('#\.(sql|md|lock|bak|bak[0-9]*|ini|log|env|sh|bash|yml|yaml|conf|dist|sample|swp|swo|orig|save|old|tmp|sqlite|db)$#i',$a)){ml_guard_deny();}if(preg_match('#/\.#',$a)){ml_guard_deny();}}}if(!function_exists('ml_guard_shield')){function ml_guard_shield($a){if(defined('ML_APP')){return;}if(php_sapi_name()==='cli'){return;}if(empty($_SERVER['SCRIPT_FILENAME'])){return;}$b=@realpath((string)$_SERVER['SCRIPT_FILENAME']);$c=@realpath((string)$a);if($b!==false&&$c!==false&&$b===$c){ml_guard_deny();}}}if(!function_exists('ml_guard_status')){function ml_guard_shield_files(){return array('core/Config.php','core/DB.php','core/Http.php','core/Json.php','core/CacheStore.php','core/Categories.php','core/LinkChecker.php','core/Views.php','core/StaticGen.php','core/InstallGuard.php','core/Settings.php','core/Sync.php','core/Site.php','core/PanSou.php','core/User.php','core/UserViews.php','core/Session.php','adapters/Adapter.php','adapters/Tmdb.php','adapters/HongguoDuanju.php','api/tmdb_proxy.php','api/unified.php','home.php','track.php','user.php','config/config.sample.php',);}function ml_guard_dirs(){return array('config','sql','core','adapters','cron','tools');}function ml_guard_file_shielded($a){if(!is_file($a)){return false;}$b=(string)@file_get_contents($a);return(strpos($b,'ml_guard_shield(')!==false);}function ml_guard_status($a){$a=rtrim(str_replace('\\','/',$a),'/');$b=array();$b['install_removed']=!file_exists($a.'/install.php');$b['install_ghosts']=array();foreach(array('install.php','setup.php','install.php.bak','install.lock.bak')as $c){if(file_exists($a.'/'.$c)){$b['install_ghosts'][]=$c;}}$b['lock']=file_exists($a.'/config/install.lock');$b['cfg_exists']=file_exists($a.'/config/config.php');$b['check_exists']=file_exists($a.'/check.php');$b['cli_installer']=file_exists($a.'/tools/install-cli.php');$b['tools_denied']=file_exists($a.'/tools/index.php');$d=array();foreach(ml_guard_dirs()as $e){$d[$e]=file_exists($a.'/'.$e.'/index.php');}$b['dir_guards']=$d;$f=array();$g=0;foreach(ml_guard_shield_files()as $h){$i=$a.'/'.$h;if(!is_file($i)){continue;}$g++;if(!ml_guard_file_shielded($i)){$f[]=$h;}}$b['shield_total']=$g;$b['shield_missing']=$f;$b['htaccess']=file_exists($a.'/.htaccess');return $b;}}ml_guard_shield(__FILE__);